package main

import (
	"fmt"
	"log/slog"
	"os"
)

func main() {
	opts := &slog.HandlerOptions{ReplaceAttr: noTime, Level: slog.LevelWarn}
	logger := slog.New(slog.NewTextHandler(os.Stdout, opts)).With("dock", 3)
	if err := run(logger); err != nil {
		logger.Error("run failed", "err", err)
		os.Exit(1)
	}
}

func run(logger *slog.Logger) error {
	defer fmt.Println("gate locked")
	logger.Info("unloading", "crates", 4)
	logger.Warn("crane slow", "minutes", 15)
	return fmt.Errorf("crate %d leaking", 2)
}

func noTime(groups []string, a slog.Attr) slog.Attr {
	if a.Key == slog.TimeKey && len(groups) == 0 {
		return slog.Attr{}
	}
	return a
}

