// Command dock ships and tracks parcels from the command line.
package main

import (
	"flag"
	"fmt"
	"os"
	"runtime/debug"
)

var release = "dev" // replaced at build time with -ldflags "-X main.release=..."

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: dock <ship|track|version> [flags]")
		os.Exit(2)
	}
	switch os.Args[1] {
	case "ship":
		ship(os.Args[2:])
	case "track":
		track(os.Args[2:])
	case "version":
		version()
	default:
		fmt.Fprintf(os.Stderr, "dock: unknown command %q\n", os.Args[1])
		os.Exit(2)
	}
}

func ship(args []string) {
	fs := flag.NewFlagSet("ship", flag.ExitOnError)
	to := fs.String("to", "Lisbon", "destination port")
	kg := fs.Int("kg", 1, "weight in kilograms")
	fs.Parse(args)
	fmt.Printf("shipping %d kg to %s\n", *kg, *to)
}

func track(args []string) {
	fs := flag.NewFlagSet("track", flag.ExitOnError)
	id := fs.Int("id", 0, "parcel number")
	fs.Parse(args)
	fmt.Printf("parcel %d is waiting at the dock\n", *id)
}

func version() {
	fmt.Println("dock", release)
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return
	}
	fmt.Println("module:", info.Main.Path)
	fmt.Println("built with:", info.GoVersion)
	for _, s := range info.Settings {
		if s.Key == "GOOS" || s.Key == "GOARCH" || s.Key == "-trimpath" {
			fmt.Println(s.Key + "=" + s.Value)
		}
	}
}

